using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();
        var app = await _appHost.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
            await disposable.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);

        var evaluator = new RelevanceEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, _chatClient);

        foreach (var metric in result)
        {
            Assert.IsTrue(
                metric.Value?.NumericValue >= 3,
                $"Metric '{metric.Key}' scored {metric.Value?.NumericValue}, expected >= 3");
        }
    }

    [TestMethod]
    public async Task Chat_ResponseIsCoherent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        var evaluator = new CoherenceEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, _chatClient);

        foreach (var metric in result)
        {
            Assert.IsTrue(
                metric.Value?.NumericValue >= 3,
                $"Metric '{metric.Key}' scored {metric.Value?.NumericValue}, expected >= 3");
        }
    }

    [TestMethod]
    public async Task Chat_ResponseIsGrounded()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Only answer based on facts."),
            new(ChatRole.User, "What year was the Eiffel Tower completed?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        var evaluator = new GroundednessEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, _chatClient);

        foreach (var metric in result)
        {
            Assert.IsTrue(
                metric.Value?.NumericValue >= 3,
                $"Metric '{metric.Key}' scored {metric.Value?.NumericValue}, expected >= 3");
        }
    }
}

